def histogram(text: str) -> dict:
    """Return a dictionary of the most frequent nonâempty words in *text*.
    If *text* is empty or contains no words, an empty dict is returned."""
    # Split on any whitespace and filter out empty strings
    words = [w for w in text.split() if w]

    if not words:
        return {}

    # Find the maximum frequency
    max_count = max(words.count(w) for w in set(words))

    # Build the result dict with all words that have the max frequency
    return {w: max_count for w in set(words) if words.count(w) == max_count}
